using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change: discriminator property renamed to "$type".
            // Preserve "Discriminator" for compatibility with existing 500K documents
            // and direct SQL queries that reference c.Discriminator.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change: id format changed from "EntityType|Key" to just "Key".
            // Preserve "Product|{Id}" format for compatibility with existing documents.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<ProductIdValueGenerator>();

            // EF Core 9 removed support for Cosmos DB indexing via HasIndex.
            // Use Cosmos DB indexing policy directly in Azure portal or IaC.
            // entity.HasIndex(p => p.Sku); // REMOVED - no longer supported

            // EF Core 9 breaking change: sync I/O now throws by default.
            // See CosmosQuery.cs for async migration.
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // If you cannot migrate all queries to async immediately, opt back in to sync:
        // optionsBuilder.UseCosmos(..., cosmosOptions => cosmosOptions.AllowSynchronousQueryExecution(true));
    }
}

